import{_ as s,C as o,o as l,c as n,a5 as h,E as t,j as e,a as i}from"./chunks/framework.D_J2JZBr.js";const _=JSON.parse('{"title":"教授与课题组","description":"按器件与工艺、电路设计、系统与架构、设计方法学四个方向簇认识上科大 IC 相关教授与课题组。","frontmatter":{"title":"教授与课题组","description":"按器件与工艺、电路设计、系统与架构、设计方法学四个方向簇认识上科大 IC 相关教授与课题组。"},"headers":[],"relativePath":"shanghaitech/faculty/index.md","filePath":"shanghaitech/faculty/index.md","lastUpdated":1795531638000}'),d={name:"shanghaitech/faculty/index.md"};function c(p,a,u,g,b,f){const r=o("FacultyList");return l(),n("div",null,[a[0]||(a[0]=h('<h1 id="教授与课题组" tabindex="-1">教授与课题组 <a class="header-anchor" href="#教授与课题组" aria-label="Permalink to &quot;教授与课题组&quot;">​</a></h1><p>本页数据以<strong>信息学院师资库，2026 年 11 月核对版本</strong>为主，结合《后摩尔器件与集成系统中心》介绍材料和课题组公开主页整理。教授职称、研究重点和招生安排可能变化，<strong>以学院与课题组当前公布为准</strong>；本页不是招生名额表，也不对导师或实验室进行排名。</p><p>四个方向簇沿用本站科研方向分类，而非学院行政划分。分方向卡片按每位老师的「主方向」展示，避免在多个小节重复出现；交叉方向仍保留在卡片标签中。要找一位老师，既可以从问题出发读 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/">科研方向</a>，也可以直接看页面后部的完整名单。</p><div class="tip custom-block"><p class="custom-block-title">怎么读这份名单</p><p>先用方向缩小范围，再点开主页阅读近期论文。一个标签只能概括部分工作：例如光计算同时涉及光子器件与计算架构，硬件安全同时涉及电路与系统。没有出现在某个分节，不代表该老师不做这方面研究。</p></div><h2 id="器件与工艺" tabindex="-1">器件与工艺 <a class="header-anchor" href="#器件与工艺" aria-label="Permalink to &quot;器件与工艺&quot;">​</a></h2><p>这个方向簇从材料和物理机制出发，关心「什么器件能做出来、它有什么特性、怎样连接到系统」。上科大相关研究覆盖自旋电子与磁存储、宽禁带半导体、光电子与集成光子、微机电系统（Micro-Electro-Mechanical Systems，MEMS）及柔性电子。许多课题横跨器件设计、微纳加工和测量，选组前应同时了解实验技能与理论先修；平台入口见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/">科研与工艺平台</a>。</p><h3 id="半导体器件与新型存储" tabindex="-1">半导体器件与新型存储 <a class="header-anchor" href="#半导体器件与新型存储" aria-label="Permalink to &quot;半导体器件与新型存储&quot;">​</a></h3><p>从磁性、自旋、低温与宽禁带材料等不同机制切入，理解器件如何实现存储、开关、传感或新型计算。方向导读：<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/devices">半导体器件与新型存储</a>。</p>',8)),t(r,{dir:"devices",primary:""}),a[1]||(a[1]=e("h3",{id:"光电子与集成光子",tabindex:"-1"},[i("光电子与集成光子 "),e("a",{class:"header-anchor",href:"#光电子与集成光子","aria-label":'Permalink to "光电子与集成光子"'},"​")],-1)),a[2]||(a[2]=e("p",null,[i("包括光电探测与激光器、光子集成电路、非线性及量子光子学，也与光计算和智能感知交叉。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/photonics"},"光电子与集成光子"),i("。")],-1)),t(r,{dir:"photonics",primary:""}),a[3]||(a[3]=e("h3",{id:"mems、传感与柔性电子",tabindex:"-1"},[i("MEMS、传感与柔性电子 "),e("a",{class:"header-anchor",href:"#mems、传感与柔性电子","aria-label":'Permalink to "MEMS、传感与柔性电子"'},"​")],-1)),a[4]||(a[4]=e("p",null,[i("关注微纳尺度的机电耦合、压电器件、传感与柔性器件，并连接医疗、机器人和射频应用。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/mems-sensors"},"MEMS、传感与柔性电子"),i("。")],-1)),t(r,{dir:"mems",primary:""}),a[5]||(a[5]=h('<h2 id="电路设计" tabindex="-1">电路设计 <a class="header-anchor" href="#电路设计" aria-label="Permalink to &quot;电路设计&quot;">​</a></h2><p>这个方向簇把器件能力变成能工作的电路，并以功耗、性能、面积及实际应用约束评价设计。上科大的公开方向既包括数字专用芯片和 FPGA，也包括脑机接口、医疗电子、电源管理、无线传能以及射频电磁。应用导向很鲜明，但「做某种应用芯片」仍需要相应的电路基础、设计工具和验证方法，不能只学上层算法。</p><h3 id="模拟、混合信号与生物医疗芯片" tabindex="-1">模拟、混合信号与生物医疗芯片 <a class="header-anchor" href="#模拟、混合信号与生物医疗芯片" aria-label="Permalink to &quot;模拟、混合信号与生物医疗芯片&quot;">​</a></h3><p>重点连接数模混合电路、植入式医疗电子与脑机接口芯片。方向导读：<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/analog-mixed">模拟与混合信号</a>。</p>',4)),t(r,{dir:"analog",primary:""}),a[6]||(a[6]=e("h3",{id:"电源管理与功率电子",tabindex:"-1"},[i("电源管理与功率电子 "),e("a",{class:"header-anchor",href:"#电源管理与功率电子","aria-label":'Permalink to "电源管理与功率电子"'},"​")],-1)),a[7]||(a[7]=e("p",null,[i("从芯片电源管理到功率变换和能量收集，连接电路、宽禁带器件应用及电气系统；相关老师分布于智慧电气科学中心等平台。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/power"},"电源管理与功率电子"),i("。")],-1)),t(r,{dir:"power",primary:""}),a[8]||(a[8]=e("h3",{id:"射频、微波与电磁",tabindex:"-1"},[i("射频、微波与电磁 "),e("a",{class:"header-anchor",href:"#射频、微波与电磁","aria-label":'Permalink to "射频、微波与电磁"'},"​")],-1)),a[9]||(a[9]=e("p",null,[i("涵盖天线、微波电路、电磁波调控与成像，与器件、医疗和人工智能辅助设计交叉。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/rf-em"},"射频、微波与电磁"),i("。")],-1)),t(r,{dir:"rf",primary:""}),a[10]||(a[10]=e("h3",{id:"数字-vlsi-与专用芯片",tabindex:"-1"},[i("数字 VLSI 与专用芯片 "),e("a",{class:"header-anchor",href:"#数字-vlsi-与专用芯片","aria-label":'Permalink to "数字 VLSI 与专用芯片"'},"​")],-1)),a[11]||(a[11]=e("p",null,[i("数字超大规模集成电路（Very Large Scale Integration，VLSI）研究连接算法、硬件架构、RTL 和物理实现，可进一步面向视觉、图形与可重构计算。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi"},"数字 VLSI 与专用芯片"),i("；完整课题组介绍示例见 "),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/vsplab"},"VSPLab"),i("。")],-1)),t(r,{dir:"digital",primary:""}),a[12]||(a[12]=h('<h2 id="系统与架构" tabindex="-1">系统与架构 <a class="header-anchor" href="#系统与架构" aria-label="Permalink to &quot;系统与架构&quot;">​</a></h2><p>这个方向簇问的是「计算如何组织，怎样高效而可信地运行」。上科大相关研究既有后摩尔中心的先进计算电路与 AI 硬件，也有系统与安全中心的体系结构、存储系统、高性能计算和系统安全。它与数字电路相邻，但常需要更完整的编程、操作系统和性能分析背景；同一个加速器问题也可能从电路、架构或系统软件三个层次切入。</p><h3 id="ai-芯片与新型计算" tabindex="-1">AI 芯片与新型计算 <a class="header-anchor" href="#ai-芯片与新型计算" aria-label="Permalink to &quot;AI 芯片与新型计算&quot;">​</a></h3><p>关注低比特、动态随机计算、边缘 AI 等计算电路与系统问题。光计算、存算一体等交叉工作还可在器件和光子学分节中找到。方向导读：<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/ai-hardware">AI 芯片与新型计算</a>。</p>',4)),t(r,{dir:"ai-hw",primary:""}),a[13]||(a[13]=e("h3",{id:"计算机体系结构与系统",tabindex:"-1"},[i("计算机体系结构与系统 "),e("a",{class:"header-anchor",href:"#计算机体系结构与系统","aria-label":'Permalink to "计算机体系结构与系统"'},"​")],-1)),a[14]||(a[14]=e("p",null,[i("从处理器与存储到高性能计算，研究硬件组织和软件系统之间的相互约束。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture"},"计算机体系结构与系统"),i("。")],-1)),t(r,{dir:"arch",primary:""}),a[15]||(a[15]=e("h3",{id:"硬件安全与隐私计算",tabindex:"-1"},[i("硬件安全与隐私计算 "),e("a",{class:"header-anchor",href:"#硬件安全与隐私计算","aria-label":'Permalink to "硬件安全与隐私计算"'},"​")],-1)),a[16]||(a[16]=e("p",null,[i("包括隐私计算芯片、侧信道、可信执行环境和微架构安全；应区分电路级攻击面与系统级威胁模型。方向导读："),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/hardware-security"},"硬件安全与隐私计算"),i("。")],-1)),t(r,{dir:"security",primary:""}),a[17]||(a[17]=h('<h2 id="设计方法学" tabindex="-1">设计方法学 <a class="header-anchor" href="#设计方法学" aria-label="Permalink to &quot;设计方法学&quot;">​</a></h2><p>电子设计自动化（Electronic Design Automation，EDA）研究设计工具与算法，而不只是使用商业软件。上科大公开方向覆盖 AI4EDA、设计空间探索、物理设计、可制造性设计和计算光刻，并与硬件安全、集成电路及光电混合计算交叉。适合既愿意理解芯片约束、又愿意钻研算法与软件实现的同学；做工具也需要知道工具最终优化和验证的对象是什么。</p><h3 id="eda-与可制造性设计" tabindex="-1">EDA 与可制造性设计 <a class="header-anchor" href="#eda-与可制造性设计" aria-label="Permalink to &quot;EDA 与可制造性设计&quot;">​</a></h3><p>方向导读：<a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA 与可制造性设计</a>。建议结合电路与设计流程课程，理解评价指标、基准设计和算法复杂度，再阅读方法论文。</p>',4)),t(r,{dir:"eda",primary:""}),a[18]||(a[18]=h('<h2 id="如何联系老师、参与课题组科研" tabindex="-1">如何联系老师、参与课题组科研 <a class="header-anchor" href="#如何联系老师、参与课题组科研" aria-label="Permalink to &quot;如何联系老师、参与课题组科研&quot;">​</a></h2><p>以下是通用建议，不代表任何课题组的录取条件或招生承诺。</p><ol><li><strong>先读公开材料。</strong> 阅读老师主页、近期两三篇论文的摘要和图表，写出自己真正想了解的问题。不需要第一封邮件就提出成熟研究方案，但要能说明为什么对这个方向感兴趣。</li><li><strong>让邮件简短、可回复。</strong> 标题写明「本科科研咨询 / 年级 / 方向」；正文说明学术背景、已修课程、相关项目、每周可投入时间和希望开始的时间。附简历或项目链接，提出一个明确请求，如是否有适合本科生的科研任务或能否预约交流。</li><li><strong>按任务准备先修。</strong> 数字芯片可从 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115b">EE115B</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">EE113</a> 与 HDL 入手；模拟方向重视 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115a">EE115A</a> 和电路分析；器件方向重视物理、半导体与实验安全；系统和 EDA 方向还需编程、算法与数学。先修建议应由具体导师进一步确认。</li><li><strong>讨论可交付的小任务。</strong> 本科科研常见起点包括论文复现、测试脚本、仿真与测量、模块实现、读书讨论和毕业论文。先确认目标、指导方式、时间安排与数据使用规则，再逐步扩大范围。</li><li><strong>区分科研参与与招生。</strong> 短期参与课题组，不自动等于保研、硕博录取、流片资格或论文署名。涉及实验设备、许可证和非公开数据时，必须遵守培训授权与保密要求。</li></ol><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你在相关课题组做过科研，欢迎通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充公开主页、研究方向和可复用的入门经验。不收集学生个人信息、私人通信或导师性格评价。</p></div><h2 id="完整名单" tabindex="-1">完整名单 <a class="header-anchor" href="#完整名单" aria-label="Permalink to &quot;完整名单&quot;">​</a></h2><p>下列为本站当前收录的 <strong>IC 相关名单</strong>，并非信息学院所有教授。部分历史材料条目在卡片中保留了来源或核验提示，不能据此推断当前招生状态。</p>',6)),t(r),a[19]||(a[19]=h('<h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/szdwx/list.htm" target="_blank" rel="noreferrer">信息学院师资库</a>：本站 <code>faculty.ts</code> 标注的主要来源，核对时间为 2026-11；每张卡片链接到对应公开主页。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔器件与集成系统中心介绍材料</a>：历史课题组名称与研究方向补充，不能替代当前师资库。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0506/c10969a1121576/page.htm" target="_blank" rel="noreferrer">走进信息学院七大研究中心，2026-05-06</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">本硕博课程体系</a>：先修准备参考；本站按 <code>directions.ts</code> 的四个方向簇组织内容。</li></ul>',2))])}const k=s(d,[["render",c]]);export{_ as __pageData,k as default};
